#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gesummv.h"

/* --------------------------------------------------------------------
 * Tunable kernel parameters
 *
 * These constants can be overridden at compile time, e.g.:
 *   -DGESUMMV_J_BLOCK=64 -DGESUMMV_OMP_MIN_N=512
 * ------------------------------------------------------------------*/

/* Blocking factor for the inner j-loop.
 * Chosen to give the compiler a small, cache-friendly working set
 * while keeping the code simple. */
#ifndef GESUMMV_J_BLOCK
# define GESUMMV_J_BLOCK 64
#endif

/* Minimum problem size for which OpenMP parallelization of the outer
 * loop is enabled (when compiled with -fopenmp). Below this size the
 * sequential version is typically faster due to threading overhead. */
#ifndef GESUMMV_OMP_MIN_N
# define GESUMMV_OMP_MIN_N 256
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    {
      x[i] = (DATA_TYPE)( i % n) / n;
      for (j = 0; j < n; j++) {
	A[i][j] = (DATA_TYPE) ((i*j+1) % n) / n;
	B[i][j] = (DATA_TYPE) ((i*j+2) % n) / n;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use local accumulators (tmp_sum, y_sum) instead of repeatedly
 *    loading/storing tmp[i] and y[i] inside the inner loop.
 *  - Derive row pointers Ai and Bi once per i-iteration to reduce
 *    address arithmetic and improve cache locality.
 *  - Use restrict-qualified local pointers (x_, y_, tmp_, Ai, Bi) to
 *    enable better auto-vectorization and alias analysis.
 *  - (Optional) Parallelize the outer i-loop with OpenMP when
 *    compiled with -fopenmp and N >= GESUMMV_OMP_MIN_N.
 *  - Apply simple blocking over the j-dimension controlled by
 *    GESUMMV_J_BLOCK to keep the working set small and improve
 *    cache behavior for large N.
 *
 * The order of floating-point operations for each (i) is preserved
 * with respect to the original code: for a fixed i, contributions
 * are accumulated in increasing j order (we only segment the j range
 * into blocks). */
static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Avoid unused-parameter warnings for n; the effective loop bound
   * is driven by PolyBench via _PB_N. */
  (void)n;

  /* Create restrict-qualified local pointers to help the compiler
   * with alias analysis, while still keeping the original arrays
   * and their layout intact. We only access the data through these
   * restricted pointers inside the kernel. */
  DATA_TYPE * restrict tmp_ = tmp;
  DATA_TYPE * restrict x_   = x;
  DATA_TYPE * restrict y_   = y;

  const DATA_TYPE alpha_c = alpha;
  const DATA_TYPE beta_c  = beta;

  /* PolyBench-controlled loop bound. */
  const int N_eff = _PB_N;
  const int J_BLOCK = GESUMMV_J_BLOCK;

#pragma scop
  /* Parallelize the outer loop when OpenMP is available and the
   * problem size is large enough. When compiled without -fopenmp,
   * _OPENMP is undefined and this pragma is skipped at preprocessing
   * time, so the code remains purely sequential. */
#if defined(_OPENMP)
#pragma omp parallel for schedule(static) if (N_eff >= GESUMMV_OMP_MIN_N)
#endif
  for (int i = 0; i < N_eff; i++)
    {
      /* Local accumulators kept in registers. */
      DATA_TYPE tmp_sum = SCALAR_VAL(0.0);
      DATA_TYPE y_sum   = SCALAR_VAL(0.0);

      /* Row pointers to improve spatial locality and reduce the
       * cost of computing A[i][j] and B[i][j] repeatedly. These
       * are private to each iteration of the i-loop. */
      DATA_TYPE * restrict Ai = A[i];
      DATA_TYPE * restrict Bi = B[i];

      /* Block the j-loop to improve cache behavior for large N.
       * For each block [jj, je), we process j in strictly
       * increasing order, preserving the original accumulation
       * order per row i. */
      for (int jj = 0; jj < N_eff; jj += J_BLOCK)
      {
        int je = jj + J_BLOCK;
        if (je > N_eff)
          je = N_eff;

        /* Vectorize innermost loop. With OpenMP enabled, we use
         * an explicit simd reduction; otherwise we give the
         * compiler a strong hint with GCC's ivdep. */
#if defined(_OPENMP)
#pragma omp simd reduction(+:tmp_sum, y_sum)
#else
#pragma GCC ivdep
#endif
        for (int j = jj; j < je; j++)
	{
	  DATA_TYPE xj = x_[j];
	  tmp_sum += Ai[j] * xj;
	  y_sum   += Bi[j] * xj;
	}
      }

      /* Write back final results for this row. This reproduces the
       * effect of the original code, where tmp[i] and y[i] are the
       * complete dot-products after the inner loop. */
      tmp_[i] = tmp_sum;
      y_[i]   = alpha_c * tmp_sum + beta_c * y_sum;
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
