#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gesummv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* Local restrict-qualified views improve alias analysis and
     allow the compiler to keep row pointers in registers. */
  DATA_TYPE (* __restrict__ A_)[n] = A;
  DATA_TYPE (* __restrict__ B_)[n] = B;
  DATA_TYPE * __restrict__ x_      = x;

  for (i = 0; i < n; i++)
    {
      /* For 0 <= i < n we have (i % n) == i, so this is
         exactly equivalent but avoids the modulo operation. */
      x_[i] = (DATA_TYPE)i / n;

      DATA_TYPE * __restrict__ Ai = A_[i];
      DATA_TYPE * __restrict__ Bi = B_[i];

      for (j = 0; j < n; j++) {
	Ai[j] = (DATA_TYPE) ((i*j+1) % n) / n;
	Bj:
	Bj = Bi[j]; /* to avoid shadowing below */
	Bj = (DATA_TYPE) ((i*j+2) % n) / n;
	Bi[j] = Bj;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Local restrict-qualified views of the arrays.  PolyBench allocates
     A, B, x, y, tmp in separate aligned regions, so this reflects the
     actual aliasing behavior and enables more aggressive optimization. */
  DATA_TYPE (* __restrict__ A_)[n] = A;
  DATA_TYPE (* __restrict__ B_)[n] = B;
  DATA_TYPE * __restrict__ tmp_    = tmp;
  DATA_TYPE * __restrict__ x_      = x;
  DATA_TYPE * __restrict__ y_      = y;

#pragma scop
  /* Each row i is completely independent, so we can safely
     parallelize across i.  If OpenMP is not enabled at compile
     time, this pragma is ignored and execution remains serial. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict__ Ai = A_[i];
      DATA_TYPE * __restrict__ Bi = B_[i];

      /* Keep the partial sums in registers to reduce memory traffic.
         We write tmp_[i] and y_[i] only once per row. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      const int j_end    = _PB_N;
      const int j_unroll = j_end - (j_end % 4); /* largest multiple of 4 <= j_end */

      /* Manually unrolled inner loop (factor 4) for better ILP and
         to give the vectorizer a straightforward pattern. */
      for (j = 0; j < j_unroll; j += 4)
	{
	  DATA_TYPE x0 = x_[j];
	  DATA_TYPE x1 = x_[j+1];
	  DATA_TYPE x2 = x_[j+2];
	  DATA_TYPE x3 = x_[j+3];

	  tmp_i += Ai[j]   * x0;
	  tmp_i += Ai[j+1] * x1;
	  tmp_i += Ai[j+2] * x2;
	  tmp_i += Ai[j+3] * x3;

	  y_i   += Bi[j]   * x0;
	  y_i   += Bi[j+1] * x1;
	  y_i   += Bi[j+2] * x2;
	  y_i   += Bi[j+3] * x3;
	}

      /* Handle the remaining elements (if j_end is not a multiple of 4). */
      for (; j < j_end; j++)
	{
	  DATA_TYPE xj = x_[j];
	  tmp_i += Ai[j] * xj;
	  y_i   += Bi[j] * xj;
	}

      /* Store the results.  tmp_[i] matches the original tmp[i] value,
         and y_[i] implements y[i] = alpha * tmp[i] + beta * y[i]. */
      tmp_[i] = tmp_i;
      y_[i]   = alpha * tmp_i + beta * y_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
