/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use of restrict-qualified local pointers to aid alias analysis.
   - Row pointers (Ai, Bi) to avoid repeated address computation.
   - Accumulation in registers (tmp_i, y_i) with a single store at the end.
   - Manual inner-loop unrolling (factor GESUMMV_J_UNROLL, default 4) while
     preserving the original floating-point evaluation order.
   - Optional OpenMP parallelization over the outer (row) loop when compiled
     with -fopenmp, without changing numerical results (rows are independent).
*/
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Use the PolyBench-provided effective problem size. */
  const int n_eff = _PB_N;

  /* Create local restrict-qualified views. This makes the aliasing
     properties explicit to the compiler and often results in better
     vectorization and fewer redundant loads/stores. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;
  DATA_TYPE *restrict tmp_    = tmp;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;

  int i;

#pragma scop
  /* Parallelize the outer loop over rows when OpenMP is enabled.
     Each iteration touches disjoint elements of tmp_ and y_ and
     only reads from A_, B_, and x_, so there are no data races.
     Without -fopenmp this pragma is ignored by the compiler. */
#pragma omp parallel for schedule(static) if (n_eff >= 128)
  for (i = 0; i < n_eff; i++)
    {
      /* Row pointers: improve cache locality and avoid re-computing
         the base address of A[i][j] and B[i][j] inside the inner loop. */
      const DATA_TYPE *restrict Ai = A_[i];
      const DATA_TYPE *restrict Bi = B_[i];

      /* Keep accumulators in registers for the whole row. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      int j = 0;

      /* Largest multiple of the unroll factor not exceeding n_eff. */
      const int limit = n_eff - (n_eff % GESUMMV_J_UNROLL);

      /* Manually unrolled inner loop.
         The order of operations for each (i, j) is identical to the
         original scalar loop:
           tmp_i <- A[i][j]*x[j] + tmp_i
           y_i   <- B[i][j]*x[j] + y_i
         We simply express several consecutive iterations explicitly
         to expose more instruction-level parallelism. */
      for (; j < limit; j += GESUMMV_J_UNROLL)
      {
#if (GESUMMV_J_UNROLL == 4)
        /* Fast path for the default unroll factor of 4. */
        const DATA_TYPE x0 = x_[j];
        const DATA_TYPE x1 = x_[j + 1];
        const DATA_TYPE x2 = x_[j + 2];
        const DATA_TYPE x3 = x_[j + 3];

        tmp_i += Ai[j]     * x0;
        y_i   += Bi[j]     * x0;

        tmp_i += Ai[j + 1] * x1;
        y_i   += Bi[j + 1] * x1;

        tmp_i += Ai[j + 2] * x2;
        y_i   += Bi[j + 2] * x2;

        tmp_i += Ai[j + 3] * x3;
        y_i   += Bi[j + 3] * x3;
#else
        /* Generic path for arbitrary positive unroll factors.
           The extra inner loop remains very small and typically
           gets fully unrolled by the compiler as well. */
#       pragma GCC ivdep
        for (int jj = 0; jj < GESUMMV_J_UNROLL; ++jj)
        {
          const int j2 = j + jj;
          const DATA_TYPE xj = x_[j2];
          tmp_i += Ai[j2] * xj;
          y_i   += Bi[j2] * xj;
        }
#endif
      }

      /* Remainder loop when n_eff is not a multiple of GESUMMV_J_UNROLL. */
      for (; j < n_eff; ++j)
      {
        const DATA_TYPE xj = x_[j];
        tmp_i += Ai[j] * xj;
        y_i   += Bi[j] * xj;
      }

      /* Store results once per row (reduced memory traffic versus
         the original version, which updated tmp[i] and y[i] every
         inner-loop iteration). The final values are identical. */
      tmp_[i] = tmp_i;
      y_[i]   = alpha * tmp_i + beta * y_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gesummv (n, alpha, beta,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(B),
		  POLYBENCH_ARRAY(tmp),
		  POLYBENCH_ARRAY(x),
		  POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
