 *  - Use scalar accumulators (tmp_i, y_i) instead of repeatedly updating
 *    tmp[i] and y[i] inside the inner loop.
 *
 * The mathematical computation and all observable side effects (the final
 * contents of tmp[] and y[]) are preserved exactly.
 */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

  /* Create local, restrict-qualified 1D views.  PolyBench allocates
     the 2D arrays as contiguous row-major buffers, so treating them as
     linear arrays is valid and preserves layout. */
  DATA_TYPE * restrict A1   = (DATA_TYPE *)A;
  DATA_TYPE * restrict B1   = (DATA_TYPE *)B;
  DATA_TYPE * restrict tmp1 = (DATA_TYPE *)tmp;
  DATA_TYPE * restrict x1   = (DATA_TYPE *)x;
  DATA_TYPE * restrict y1   = (DATA_TYPE *)y;

  const int nn = n; /* Row length / leading dimension */

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Per-row accumulators; initialize as in the original code
         (tmp[i] = 0; y[i] = 0;) but kept in registers. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE y_i   = SCALAR_VAL(0.0);

      /* Pointers to the current rows of A and B.
         Using row pointers keeps the inner loop address computation
         simple and amenable to vectorization. */
      const DATA_TYPE * restrict Arow = A1 + (size_t)i * nn;
      const DATA_TYPE * restrict Brow = B1 + (size_t)i * nn;

