	  tmp_i += Arow[j] * xj;
	  y_i   += Brow[j] * xj;
	}

      /* Store results back to arrays, preserving original semantics. */
      tmp1[i] = tmp_i;
      y1[i]   = alpha * tmp_i + beta * y_i;
    }
#pragma endscop

